@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
  + institutionCode : int
}

class ResearchInstitution {
  + institutionCode : int
  + name : string
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + authorPositions : int[]
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
  + reviewers : Person[]
}

class TechnicalReport extends ScientificArticle {}

class Publisher {
  + name : string
}

class Journal {
  + publisherName : string
  + journalName : string
  + impactFactor : float
}

Person "1" -- "0..*" ResearchInstitution : worksFor
ResearchInstitution "1" *-- "0..*" ScientificArticle : publishes
ScientificArticle "0..*" -- "0..*" Person : authoredBy
PeerReviewedPaper "0..*" -- "0..*" Person : reviewedBy
TechnicalReport "1" -- "1" ResearchInstitution : publishedBy
Publisher "1" *-- "0..*" Journal : publishes

@enduml

